@startuml

class Customer {
  + Name : string
  + PhoneNumber : string
}

class Table {
  + NumberOfSeats : int
  + IsSmoking : boolean
}

class Reservation {
  + Day : date
  + Time : time
  + NumberOfPeople : int
}

class Waiter {
  + Name : string
  + YearsOfService : int
}

class Bill {
  + TotalAmount : double
}

class Dish {
  + Name : string
  + UnitPrice : double
}

class BillLine {
  + Quantity : int
}

Customer "1" -- "0..*" Reservation : makes
Reservation "0..*" -- "1..*" Table : assigns
Waiter "1" -- "0..*" Customer : serves
Customer "1" -- "0..*" Bill : pays
Bill "1" *-- "1..*" BillLine : consists of
BillLine "0..*" -- "1" Dish : includes

@enduml

